query Query($where: PackagingConfigurationWhereInput, $orderBy: [PackagingConfigurationOrderByInput!], $first: Int, $after: String) {
  packagingConfiguration(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        code

        height {
          value
          unit {
            code
          }
        }
        length {
          value
          unit {
            code
          }
        }

        width {
          value
          unit {
            code
          }
        }
        tareWeight{
          value
          unit {
            code
          }
        }

        process {
          id
          code
        }
        processId
        product {
          id
          code
          number
        }
        productId
        productProcess {
          id
          code
        }
        productProcessId

        document {
          id
          name
        }
        documentId
      }
    }
  }
}

query Query($where: PackagingConfigurationDetailWhereInput, $orderBy: [PackagingConfigurationDetailOrderByInput!], $first: Int, $after: String) {
  packagingConfigurationDetail(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        layerHeight
        layerQuantity
        order
        grossWeight {
          value
          unitId
          unit {
            id
            unitTypeId
            name
            code
          }
        }
        netWeight {
          value
          unitId
          unit {
            id
            unitTypeId
            name
            code
          }
        }
        productQuantity
        return
        tareWeight {
          value
          unitId
        }
        material {
          id
          code
        }
        document {
          id
          name
        }
        product {
          id
          code
        }
      }
    }
  }
}
